#include <bits/stdc++.h>
using namespace std;

double angleBetweenPoints(const vector<int>& p1, const vector<int>& p2, const vector<int>& p3) {
    double dotProduct = 0.0, lengthA = 0.0, lengthB = 0.0;
    for (int i = 0; i < 5; i++) {
        double v1 = p2[i] - p1[i];
        double v2 = p3[i] - p1[i];
        dotProduct += v1 * v2;
        lengthA += v1 * v1;
        lengthB += v2 * v2;
    }
    return 180.0 * acos(dotProduct / sqrt(lengthA * lengthB)) / M_PI;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n > 20) {
        cout << 0 << "\n";
    } else {
        vector<vector<int>> coords(n, vector<int>(5));
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                cin >> coords[i][j];
            }
        }
        vector<int> selected;
        for (int i = 0; i < n; i++) {
            bool skip = false;
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    for (int k = j + 1; k < n; k++) {
                        if (i != k) {
                            if (angleBetweenPoints(coords[i], coords[j], coords[k]) < 90) {
                                skip = true;
                                break;
                            }
                        }
                    }
                }
                if (skip) break;
            }
            if (!skip) {
                selected.push_back(i + 1);
            }
        }
        cout << selected.size() << "\n";
        for (int index : selected) {
            cout << index << "\n";
        }
    }
    return 0;
}
